message.content:
{
  "candidate_edge_types": [
    {
      "name": "ATTEMPTS_TO_RESOLVE_EXECUTION_ERROR",
      "definition": "A subsequent agent action attempts to remove a failure or blocking prerequisite reported by an earlier execution step, after which the previously failing step is re-executed to continue the pipeline.",
      "source_description": "An earlier tool execution result reporting a failure, exception, or missing prerequisite that blocks progress toward the task goal.",
      "target_description": "A subsequent agent action intended to remove the blocking cause (for example by installing or providing the missing dependency) so that the failed step can proceed."
    },
    {
      "name": "INVESTIGATES_ANOMALOUS_EXECUTION_RESULT",
      "definition": "A subsequent agent action gathers additional diagnostic evidence (such as printing intermediate values, per-candidate scores, or raw input renderings) in order to explain an earlier execution result that is implausible, self-contradictory, or suspicious.",
      "source_description": "An earlier tool observation whose output is anomalous or inconsistent with expectations, indicating a likely flaw in the current method.",
      "target_description": "A subsequent agent action that produces diagnostic evidence about the cause of the anomaly rather than directly correcting the task outcome."
    },
    {
      "name": "REPLACES_STRATEGY_AFTER_DIAGNOSIS",
      "definition": "Based on diagnostic evidence explaining why the current method cannot succeed, the agent abandons that method and performs an action that implements a fundamentally different strategy to achieve the same subgoal.",
      "source_description": "A diagnostic observation revealing the root cause that makes the current method unsuitable for the task.",
      "target_description": "A subsequent agent action implementing a different strategy in place of the abandoned method."
    },
    {
      "name": "CONSUMES_PRIOR_OUTPUT_ARTIFACT",
      "definition": "A subsequent agent action references or consumes an artifact (file, recorded listing, or computed value) produced by an earlier tool execution, using it directly as input for the next step of the same analysis.",
      "source_description": "An earlier tool execution result that produced a persistent artifact or recorded value.",
      "target_description": "A subsequent agent action that reads or otherwise consumes that artifact or value as its input."
    }
  ]
}

